    pub fn handle_ohlcv(&mut self, mut client: Value, message: &Value) {
        let __message_empty = indexmap::IndexMap::new();
        let message = message.as_map().unwrap_or(&__message_empty);
        //
        //     {
        //         data: {
        //             E: '1754519557526056',
        //             T: '2025-08-07T00:00:00',
        //             X: false,
        //             c: '3680.520000000',
        //             e: 'kline',
        //             h: '3681.370000000',
        //             l: '3667.650000000',
        //             n: 255,
        //             o: '3670.150000000',
        //             s: 'ETH_USDC',
        //             t: '2025-08-06T22:00:00',
        //             v: '62.2621000'
        //         },
        //         stream: 'kline.2h.ETH_USDC'
        //     }
        //
        let data: crate::value::Dict = message.key_dict("data");
        let marketId: Option<String> = self.safe_string_k_opt(&data, "s", &[]);
        let mut market: crate::types::Market = (match self.market(marketId.as_deref().unwrap_or_default()) { Ok(__mk) => __mk, Err(__e) => panic!("{}", __e) });
        let symbol: String = self.safe_string_k(&market, "symbol", &[Value::Str("".into())]).as_str().unwrap_or("").to_string();
        let stream: String = (match message.get("stream") { Some(Value::Str(__s)) if !__s.is_empty() => __s.to_string(), Some(Value::Int(__n)) => __n.to_string(), Some(Value::Float(__f)) => __f.to_string(), _ => "".to_string() });
        let parts: crate::value::List = crate::value::List::new(stream.split(".").map(Value::from).collect());
        let timeframe: String = self.safe_string(&parts, Value::Int(1), &[Value::Str("".into())]).as_str().unwrap_or("").to_string();
        if !(CacheShelves::has(&self.ohlcvs, &symbol)) {
            CacheShelves::reset(&mut self.ohlcvs, &symbol);
        }
        if !(self.ohlcvs.shelf(&symbol).has(&timeframe)) {
            let limit: i64 = self.safe_integer_k(&self.options, "OHLCVLimit", &[Value::Int(1000)]).as_i64().unwrap_or(1000);
            let stored: crate::pro::cache::Cache = ArrayCacheByTimestamp::new(Value::from(limit));
            CacheShelves::put2(&mut self.ohlcvs, &symbol, &timeframe, stored);
        }
        let mut ohlcv: Option<crate::pro::cache::Cache> = self.ohlcvs.shelf(&symbol).at(&timeframe);
        let parsed: crate::value::List = self.parse_ws_ohlcv(Value::Dict(data), None);
        ohlcv.append(Value::Arr(parsed));
        let messageHash: String = format!("{}{}", Value::Str(format!("{}{}", Value::Str(format!("{}{}", "candles:", symbol).into()), ":").into()), timeframe);
        client.resolve(Value::from(vec![Value::from(symbol), Value::from(timeframe), Value::from(&ohlcv)]), messageHash.as_str());
}

    pub fn parse_ws_ohlcv(&self, mut ohlcv: Value, market: Option<&crate::types::Market>) -> crate::value::List {
        return std::sync::Arc::new(vec![Value::from(self.parse8601(self.safe_string_k(&ohlcv, "t", &[]))), self.safe_number_k(&ohlcv, "o", &[]), self.safe_number_k(&ohlcv, "h", &[]), self.safe_number_k(&ohlcv, "l", &[]), self.safe_number_k(&ohlcv, "c", &[]), self.safe_number_k(ohlcv, "v", &[])]);
}

