    pub fn handle_trades(&mut self, client: &Value, message: &Value) {
        let __message_empty = indexmap::IndexMap::new();
        let message = message.as_map().unwrap_or(&__message_empty);
        //
        //     {
        //         data: {
        //             E: '1754601477746429',
        //             T: '1754601477744000',
        //             a: '5121860761',
        //             b: '5121861755',
        //             e: 'trade',
        //             m: false,
        //             p: '3870.25',
        //             q: '0.0008',
        //             s: 'ETH_USDC_PERP',
        //             t: 10782547
        //         },
        //         stream: 'trade.ETH_USDC_PERP'
        //     }
        //
        let data: crate::value::Dict = message.key_dict("data");
        let marketId: Option<String> = self.safe_string_k_opt(&data, "s", &[]);
        let mut market: crate::types::Market = (match self.market(marketId.as_deref().unwrap_or_default()) { Ok(__mk) => __mk, Err(__e) => panic!("{}", __e) });
        let symbol: String = self.safe_string_k(&market, "symbol", &[Value::Str("".into())]).as_str().unwrap_or("").to_string();
        if !(self.trades.has(&symbol)) {
            let limit: i64 = self.safe_integer_k(&self.options, "tradesLimit", &[Value::Int(1000)]).as_i64().unwrap_or(1000);
            let stored: crate::pro::cache::Cache = ArrayCache::new(Value::from(limit));
            CacheStore::put(&mut self.trades, &symbol, stored);
        }
        let mut cache: Option<crate::pro::cache::Cache> = self.trades.at(&symbol);
        let trade: crate::value::Dict = self.parse_ws_trade(&data, Some(&market));
        cache.append(Value::Dict(trade));
        let messageHash: String = format!("{}{}", "trades:", symbol);
        client.resolve(Value::from(&cache), messageHash.as_str());
        client.resolve(Value::from(&cache), "trades");
}

    pub fn parse_ws_trade(&self, trade: impl Into<crate::Value>, market: Option<&crate::types::Market>) -> crate::value::Dict {
        let trade: Value = trade.into();
        //
        //     {
        //         E: '1754601477746429',
        //         T: '1754601477744000',
        //         a: '5121860761',
        //         b: '5121861755',
        //         e: 'trade',
        //         m: false,
        //         p: '3870.25',
        //         q: '0.0008',
        //         s: 'ETH_USDC_PERP',
        //         t: 10782547
        //     }
        //
        let microseconds: i64 = self.safe_integer_k(&trade, "E", &[Value::Int(0)]).as_i64().unwrap_or(0);
        let timestamp: Option<i64> = self.parse_to_int(Value::Float(((microseconds as f64) / 1000.0)));
        let id: Option<String> = self.safe_string_k_opt(&trade, "t", &[]);
        let marketId: Option<String> = self.safe_string_k_opt(&trade, "s", &[]);
        let marketResolved: crate::types::Market = self.safe_market(marketId.as_deref(), market, &[]);
        let isBuyerMaker: Option<bool> = self.safe_bool_k_opt(&trade, "m", &[]);
        let mut side: Option<String> = None;
        let mut takerOrMaker: Option<String> = None;
        if (isBuyerMaker.is_some()) {
            takerOrMaker = Some("taker".to_string());
            if (isBuyerMaker == Some(true)) {
                side = Some("sell".to_string());
            }  else {
                side = Some("buy".to_string());
            }
        }
        let price: Option<String> = self.safe_string_k_opt(&trade, "p", &[]);
        let amount: Option<String> = self.safe_string_k_opt(&trade, "q", &[]);
        let mut orderId: Option<String> = None;
        if (side.as_deref() == Some("buy")) {
            orderId = self.safe_string_k_opt(&trade, "b", &[]);
        }  else {
            orderId = self.safe_string_k_opt(&trade, "a", &[]);
        }
        return self.safe_trade(std::sync::Arc::new({
    let mut m = indexmap::IndexMap::new();
        m.insert("info".to_string(), trade);
        m.insert("id".to_string(), id.map(Value::from).unwrap_or(Value::Null));
        m.insert("timestamp".to_string(), Value::from(timestamp));
        m.insert("datetime".to_string(), self.iso8601(timestamp));
        m.insert("symbol".to_string(), crate::value::KeyRead::key_read(&&marketResolved, "symbol"));
        m.insert("order".to_string(), orderId.map(Value::from).unwrap_or(Value::Null));
        m.insert("type".to_string(), Value::Null);
        m.insert("side".to_string(), side.map(Value::from).unwrap_or(Value::Null));
        m.insert("takerOrMaker".to_string(), takerOrMaker.map(Value::from).unwrap_or(Value::Null));
        m.insert("price".to_string(), price.map(Value::from).unwrap_or(Value::Null));
        m.insert("amount".to_string(), amount.map(Value::from).unwrap_or(Value::Null));
        m.insert("cost".to_string(), Value::Null);
        m.insert("fee".to_string(), Value::Map({
    let mut m = indexmap::IndexMap::new();
        m.insert("currency".to_string(), Value::Null);
        m.insert("cost".to_string(), Value::Null);
    m
}));
    m
}), Some(&marketResolved));

    Default::default()
}

